solution:
package main

import "fmt"

type Book struct {
	Title  string
	Author string
	Year   int
}

func (b Book) String() string {
	return fmt.Sprintf("%s by %s (%d)", b.Title, b.Author, b.Year)
}

func main() {
	b := Book{"Malleshwari", "Rachakonda", 1950}
	fmt.Println(b)
}
